namespace fs=std::filesystem;
fs::path root,exeDir;std::string token;unsigned sequence=0;
void need(bool b,const char* s){if(!b)throw std::runtime_error(s);}
std::string read(const fs::path& p){std::ifstream f(p,std::ios::binary);need(bool(f),"File not found");return {std::istreambuf_iterator<char>(f),{}};}
void write(const fs::path& p,const std::string& s){need(!fs::exists(p),"File already exists");std::ofstream f(p,std::ios::binary);f.exceptions(std::ios::failbit|std::ios::badbit);f<<s;}
std::string decode(const std::string& s){std::string o;for(std::size_t i=0;i<s.size();++i){if(s[i]=='+')o+=' ';else if(s[i]=='%'){need(i+2<s.size(),"Bad URL encoding");auto digit=[](char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;};int a=digit(s[i+1]),b=digit(s[i+2]);need(a>=0&&b>=0,"Bad URL encoding");o+=static_cast<char>(a*16+b);i+=2;}else o+=s[i];}need(o.find('\0')==o.npos,"NUL not allowed");return o;}
std::map<std::string,std::string> form(const std::string& s){std::map<std::string,std::string> m;std::size_t p=0;while(p<s.size()){auto e=s.find('&',p);if(e==s.npos)e=s.size();auto v=s.substr(p,e-p);auto eq=v.find('=');need(eq!=v.npos,"Invalid form");auto k=decode(v.substr(0,eq));need(!m.count(k),"Duplicate form field");m[k]=decode(v.substr(eq+1));p=e+1;}return m;}
std::string newId(){return std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count())+"-"+std::to_string(++sequence);}
std::string cfView(std::string html,bool factors=false){html+="<style>nav,#generator{display:none!important}</style><script>tab('"+std::string(factors?"factors":"payments")+"')</script>";return html;}
void calculateCF(const fs::path& input,const fs::path& output){auto exe=exeDir/L"dashboard.exe";std::wstring cmd=L"\""+exe.wstring()+L"\" \""+input.wstring()+L"\" \""+output.wstring()+L"\"";STARTUPINFOW si{};si.cb=sizeof(si);PROCESS_INFORMATION pi{};need(CreateProcessW(exe.c_str(),cmd.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,root.c_str(),&si,&pi)!=0,"Cannot launch C++ CF validator");auto wait=WaitForSingleObject(pi.hProcess,60000);if(wait!=WAIT_OBJECT_0){TerminateProcess(pi.hProcess,1);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);throw std::runtime_error("CF validation timeout");}DWORD exit=1;GetExitCodeProcess(pi.hProcess,&exit);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);need(exit==0,"CF validation failed: check headers, IDs, dates, numeric values, totals, flow_count and balances");}
void sendAll(SOCKET s,const std::string& data){std::size_t p=0;while(p<data.size()){int n=send(s,data.data()+p,static_cast<int>(std::min<std::size_t>(data.size()-p,65536)),0);if(n<=0)return;p+=n;}}
void reply(SOCKET s,int status,const std::string& body,const std::string& type="text/plain; charset=utf-8"){std::string h="HTTP/1.1 "+std::to_string(status)+(status==200?" OK":" Error")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+std::to_string(body.size())+"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\n";if(type=="text/csv"||type=="application/octet-stream")h+="Content-Disposition: attachment\r\n";sendAll(s,h+"\r\n"+body);}
void serve(SOCKET s){try{DWORD timeout=10000;setsockopt(s,SOL_SOCKET,SO_RCVTIMEO,reinterpret_cast<char*>(&timeout),sizeof(timeout));setsockopt(s,SOL_SOCKET,SO_SNDTIMEO,reinterpret_cast<char*>(&timeout),sizeof(timeout));std::string request;char buf[8192];auto head=request.npos;while((head=request.find("\r\n\r\n"))==request.npos){int n=recv(s,buf,sizeof(buf),0);need(n>0,"Incomplete request");request.append(buf,n);need(request.size()<65536,"Header too large");}std::istringstream lines(request.substr(0,head));std::string method,path,protocol,line;lines>>method>>path>>protocol;std::getline(lines,line);std::map<std::string,std::string> headers;while(std::getline(lines,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();auto colon=line.find(':');need(colon!=line.npos,"Invalid header");auto k=line.substr(0,colon);std::transform(k.begin(),k.end(),k.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});auto v=line.substr(colon+1);while(!v.empty()&&v[0]==' ')v.erase(0,1);need(!headers.count(k),"Duplicate header");headers[k]=v;}need(headers["host"]=="127.0.0.1:8765"||headers["host"]=="localhost:8765","Invalid Host");if(headers.count("origin"))need(headers["origin"]=="http://127.0.0.1:8765"||headers["origin"]=="http://localhost:8765","Cross-origin denied");need(!headers.count("transfer-encoding"),"Chunked requests unsupported");std::size_t length=0;if(headers.count("content-length")){auto v=headers["content-length"];need(!v.empty()&&std::all_of(v.begin(),v.end(),[](char c){return c>='0'&&c<='9';}),"Invalid length");length=std::stoull(v);}need(length<=16*1024*1024,"Request exceeds 16 MB");auto body=request.substr(head+4);while(body.size()<length){int n=recv(s,buf,sizeof(buf),0);need(n>0,"Incomplete body");body.append(buf,n);}need(body.size()==length,"Invalid body length");
 if(method=="POST"){need(headers["x-token"]==token,"Invalid session token");auto m=form(body);if(path=="/generate"||path=="/validate"){need(m.size()==1&&m.count("config"),"Expected config");auto id=newId();auto dir=root/"app-runs"/id;fs::create_directories(dir);write(dir/"input.ini",m.at("config"));auto c=pg::load(dir/"input.ini");if(path=="/validate"){reply(s,200,"OK");return;}need(c.count<=100000,"Interactive mode limit: 100000 deals");auto d=pg::generate(c);pg::report(c,d,dir/"result");reply(s,200,"/run/"+id+"/report.html");return;}if(path=="/import"){need(m.size()==2&&m.count("summary")&&m.count("flows"),"Expected both CSV files");auto id=newId();auto dir=root/"app-runs"/id;fs::create_directories(dir/"input");write(dir/"input/deal_summary.csv",m.at("summary"));write(dir/"input/cashflows.csv",m.at("flows"));fs::create_directory(dir/"result");calculateCF(dir/"input",dir/"result/report.html");reply(s,200,"/run/"+id+"/report.html");return;}throw std::runtime_error("Unknown operation");}
 need(method=="GET","Method unsupported");if(path=="/health"){reply(s,200,"OK");return;}if(path=="/"){auto html=read(root/"web/index.html");auto pos=html.find("SESSION_TOKEN");need(pos!=html.npos,"UI token marker missing");html.replace(pos,13,token);reply(s,200,html,"text/html; charset=utf-8");return;}if(path=="/payments"||path=="/factors"){reply(s,200,cfView(read(root/"reports/builtin-demo.html"),path=="/factors"),"text/html; charset=utf-8");return;}if(path.rfind("/run/",0)==0){auto p=path.find('/',5);need(p!=path.npos,"Invalid run");auto id=path.substr(5,p-5),name=path.substr(p+1);need(!id.empty()&&std::all_of(id.begin(),id.end(),[](char c){return (c>='0'&&c<='9')||c=='-';}),"Invalid run ID");need(std::set<std::string>{"report.html","portfolio.csv","config.ini","summary.txt","portfolio_cashflows.csv","factor_analysis.csv"}.count(name)!=0,"Invalid file");auto dir=root/"app-runs"/id;auto content=read(dir/"result"/name);if(name=="report.html"&&fs::exists(dir/"input/cashflows.csv"))content=cfView(content);reply(s,200,content,name=="report.html"?"text/html; charset=utf-8":(name=="portfolio.csv"||name=="portfolio_cashflows.csv"||name=="factor_analysis.csv")?"text/csv":"application/octet-stream");return;}reply(s,404,"Not found");
 }catch(const std::exception& e){reply(s,400,e.what());}}
int main(int argc,char** argv){try{wchar_t exe[32768];need(GetModuleFileNameW(nullptr,exe,32768)>0,"Cannot locate application");root=fs::path(exe).parent_path().parent_path().parent_path();exeDir=fs::path(exe).parent_path();need(fs::exists(root/"web/index.html"),"UI missing");
auto demoReport=root/"reports/builtin-demo.html";
if(!fs::exists(demoReport)){
    fs::create_directories(demoReport.parent_path());
    calculateCF(root/"tests/fixtures/cf",demoReport);
    std::ofstream label(demoReport,std::ios::binary|std::ios::app);
    label<<"<script>document.querySelector('#payments h2').textContent="
           "'CF DEMO: synthetic data';</script>";
}
std::random_device random;std::ostringstream key;key<<std::hex;for(int i=0;i<8;++i)key<<random();token=key.str();WSADATA data;need(WSAStartup(MAKEWORD(2,2),&data)==0,"WSAStartup failed");SOCKET listener=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);need(listener!=INVALID_SOCKET,"Socket failed");BOOL exclusive=TRUE;setsockopt(listener,SOL_SOCKET,SO_EXCLUSIVEADDRUSE,reinterpret_cast<char*>(&exclusive),sizeof(exclusive));sockaddr_in address{};address.sin_family=AF_INET;address.sin_port=htons(8765);inet_pton(AF_INET,"127.0.0.1",&address.sin_addr);need(bind(listener,reinterpret_cast<sockaddr*>(&address),sizeof(address))==0,"Port 8765 occupied; close the previous application");need(listen(listener,8)==0,"Listen failed");std::cout<<"Portfolio app: http://127.0.0.1:8765 (Ctrl+C to stop)\n"<<std::flush;if(!(argc==2&&std::string(argv[1])=="--no-browser"))ShellExecuteW(nullptr,L"open",L"http://127.0.0.1:8765",nullptr,nullptr,SW_SHOWNORMAL);for(;;){SOCKET client=accept(listener,nullptr,nullptr);if(client==INVALID_SOCKET)break;serve(client);closesocket(client);}closesocket(listener);WSACleanup();return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
